import { gql } from '@apollo/client';
import { memo } from 'radash';
import browser, { Cookies } from 'webextension-polyfill';
import { Logger } from '@shared/logger/types';
import { ExtensionMessaging } from '@shared/messages/createExtensionMessaging';
import { WEBSITE_BASE_URL } from '@shared/utils/baseUrl';
import { GraphQLClient } from '@background/api/createGraphQLClient';
import { Authenticator } from '@background/auth/createAuthenticator';
import { CookieManager } from '@background/cookies/createCookieManager';
import { BrowserStorage } from '../storage/createStorage';

export type User = {
  countryCode: string;
  created: number;
  email: string;
  name: string;
  profilePictureId: string;
  userId: string;
};

type UserPoints = {
  pointsAvailableFormatted: string;
  pointsPendingFormatted: string;
  pointsTotalFormatted: string;
  pointsAvailable: number;
  pointsPending: number;
  pointsTotal: number;
};

type UserProfileCache = {
  loginTimestamp: number;
  user: User;
};

type GetUserParams = {
  forceRefresh?: boolean;
};

export type UserManager = {
  getUserId(): Promise<string | null>;
  getUser(params?: GetUserParams): Promise<User | null>;
  getUserPoints(): Promise<UserPoints | null>;
  getAnonymousId(): Promise<string>;
  getInstallFlags(): Promise<{ hasPriorSyncId: boolean; hasPriorCookieId: boolean }>;
  isPieEmployee(): Promise<boolean>;
  start(): void;
};

export default function createUserManager({
  messages,
  authenticator,
  graphQLClient,
  logger,
  localStorage,
  cookieManager,
}: {
  localStorage: BrowserStorage;
  messages: ExtensionMessaging;
  authenticator: Authenticator;
  graphQLClient: GraphQLClient;
  logger: Logger;
  cookieManager: CookieManager;
}): UserManager {
  const USER_PROFILE_CACHE_KEY = 'pieUserProfile';
  const appId = process.env.APP_ID as string;
  let hasPriorSyncId = false;
  let hasPriorCookieId = false;

  async function getAnonymousCookie(): Promise<Cookies.Cookie | null> {
    return (
      cookieManager.get({
        url: WEBSITE_BASE_URL,
        name: `extension-${process.env.EXTENSION_TYPE}-anonymous-id`,
      }) || { value: null, expirationDate: null }
    );
  }

  async function getAnonymousIdFromCookie() {
    const cookie = await getAnonymousCookie();
    return cookie?.value || null;
  }

  async function setAnonymousIdInStorage(anonymousId: string) {
    await browser.storage.sync.set({ anonymousId });
    await browser.storage.local.set({ anonymousId }); // also set into local storage
    if (appId) {
      await browser.runtime.sendNativeMessage(appId, {
        name: 'setAnonymousId',
        data: anonymousId,
      });
    }
  }

  const getAnonymousId = memo(async () => {
    let anonymousId = '';
    // Prioritize anonymousId synced through native app (i.e. iOS or macOS bundled app)
    if (appId) {
      anonymousId = await browser.runtime.sendNativeMessage(appId, {
        name: 'getAnonymousId',
      });
    }

    // Fall back to synced anonymous ID (syncs across devices everywhere, except Desktop and Mobile Safari, which treats it as local storage)
    if (!anonymousId) {
      const values = (await browser.storage.sync.get('anonymousId')) || (await browser.storage.local.get('anonymousId'));
      anonymousId = values.anonymousId;
      if (anonymousId) {
        hasPriorSyncId = true;
      }
    }

    const anonymousIdFromCookie = (await getAnonymousIdFromCookie()) as string;
    if (anonymousIdFromCookie) {
      if (!anonymousId) {
        anonymousId = anonymousIdFromCookie;
      }
      hasPriorCookieId = true;
    }

    // if there is still no anonymousId, generate a new one
    if (!anonymousId) {
      anonymousId = crypto.randomUUID();
      await setAnonymousIdInStorage(anonymousId);
    }
    return anonymousId;
  });

  async function setAnonymousIdCookie(anonymousId?: string) {
    if (process.env.PLATFORM === 'sf') {
      const canSetCookie = await browser.permissions.contains({ permissions: ['cookies'], origins: [`${WEBSITE_BASE_URL}/`] });
      if (!canSetCookie) {
        // Can't set cookie before we have permissions for domain.
        return;
      }
    }

    await fetch(`${WEBSITE_BASE_URL}/ext/enabled`, {
      method: 'POST',
      credentials: 'include',
      headers: {
        'Cache-Control': 'no-cache',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        anonymousId,
        extensionType: process.env.EXTENSION_TYPE,
      }),
    });
  }

  function formatPoints(points: number) {
    return Intl.NumberFormat(navigator.language).format(points);
  }

  function toPoints(millipoints: number) {
    return Math.floor(millipoints / 1000);
  }

  async function getUserPoints(): Promise<UserPoints | null> {
    const {
      error,
      data: { getUserpoints: userPoints },
    } = await graphQLClient.query({
      query: gql`
        query getUserpoints {
          getUserpoints {
            millipointsAvailable
            millipointsPending
          }
        }
      `,
    });

    if (error) {
      logger.error('Failed to fetch user points', error);

      return null;
    }

    const pointsTotal = toPoints(userPoints.millipointsAvailable + userPoints.millipointsPending);
    const pointsAvailable = toPoints(userPoints.millipointsAvailable);
    const pointsPending = toPoints(userPoints.millipointsPending);

    return {
      pointsTotalFormatted: formatPoints(pointsTotal),
      pointsAvailableFormatted: formatPoints(pointsAvailable),
      pointsPendingFormatted: formatPoints(pointsPending),
      pointsTotal,
      pointsAvailable,
      pointsPending,
    };
  }

  async function getInstallFlags() {
    await getAnonymousId(); // ensure this is called at least once
    return { hasPriorSyncId, hasPriorCookieId };
  }

  let fetchUserPromise: Promise<User | null> | null = null;
  async function fetchUser({ forceRefresh }: GetUserParams = {}) {
    const getUserData = async () => {
      const loginTimestampCookie = await cookieManager.get({
        url: WEBSITE_BASE_URL,
        name: 'login-timestamp',
      });

      if (!forceRefresh) {
        const cachedUserProfile = (await localStorage.get(USER_PROFILE_CACHE_KEY)) as UserProfileCache | null;

        if (cachedUserProfile && loginTimestampCookie) {
          /**
           * If cookie for login-timestamp is newer than the cached user profile, we need to refresh the user profile.
           * This would indicate that the user has logged out and logged back in since the data was cached (possibly with a different account).
           */
          const needsRefresh = +loginTimestampCookie.value > cachedUserProfile.loginTimestamp;

          if (!needsRefresh) {
            return cachedUserProfile.user;
          }
        }
      }

      const {
        data: { getProfile: profile },
        error,
      } = await graphQLClient.query({
        query: gql`
          query getProfile {
            getProfile {
              countryCode
              created
              email
              userId
            }
          }
        `,
      });

      if (error) {
        throw new Error('User is not logged in. Check to see if user is logged in before calling fetchUser()');
      }

      const user = (await profile) as User;

      if (user && loginTimestampCookie) {
        await localStorage.set(USER_PROFILE_CACHE_KEY, {
          loginTimestamp: +loginTimestampCookie.value,
          user,
        });
      }

      return user || null;
    };

    if (forceRefresh) {
      return getUserData();
    }

    if (!fetchUserPromise) {
      fetchUserPromise = getUserData().finally(() => {
        fetchUserPromise = null;
      });
    }

    return fetchUserPromise;
  }

  async function getUser({ forceRefresh = false }: { forceRefresh?: boolean } = {}) {
    const { isLoggedIn } = await authenticator.getLoginState();

    if (!isLoggedIn) {
      return null;
    }

    return fetchUser({ forceRefresh }).catch(async (res) => {
      // It's likely the user's cookie is unreachable by the extension due to an unsupported cookie policy for the browser (likely due to an API bug).
      // Force the user to log in again to repair the cookie.
      if (res.networkError.statusCode === 401) {
        // The cookie URL needs to match the domain of the cookie being removed exactly or the extension won't remove it.
        const { domain } =
          (await cookieManager.get({
            url: WEBSITE_BASE_URL,
            name: 'is-logged-in',
          })) || {};
        cookieManager.remove({
          url: `https://${domain}/`,
          name: 'is-logged-in',
        });
      }

      return null;
    });
  }

  async function getUserId() {
    try {
      const { userId } = (await getUser()) || {};
      return userId || null;
    } catch (_) {
      return null;
    }
  }

  async function isPieEmployee() {
    const user = await getUser();
    return user?.email?.includes('@pie.org') || false;
  }

  async function start() {
    // This is being fired and continued on, the cookie setting is async and doesnt need to pause other actions
    getAnonymousCookie().then((cookie: Cookies.Cookie | null) => {
      const cookieId = cookie?.value || null;

      // set initial anonymous cookie if it doesn't exist
      if (!cookieId) {
        // getAnonymousId has to run atleast once in this scenario ... it relies functions above to ensure it follows the rules
        getAnonymousId().then(setAnonymousIdCookie);
      }
      // If cookie will expire in less than 60 days refresh it
      if (cookieId && cookie?.expirationDate && cookie?.expirationDate < Date.now() / 1000 + 60 * 60 * 24 * 60) {
        setAnonymousIdCookie(cookieId);
      }
    });

    messages.addListener('users:action:getCurrent', () => getUser());
    messages.addListener('users:action:getUserPoints', () => getUserPoints());

    messages.addListener('account:action:logout', () =>
      graphQLClient.mutate({
        mutation: gql`
          mutation logout {
            logout
          }
        `,
      }),
    );

    messages.addListener('account:action:delete', () =>
      cookieManager.set({
        url: WEBSITE_BASE_URL,
        name: 'deleteAccount',
        value: 'true',
        expirationDate: new Date().getTime() / 1000 + 60 * 60, // Expires in 1 hour
        secure: true,
      }),
    );

    // pre-cache user on start
    getUser().catch((err) => {
      logger.error('Failed to pre-cache user profile', err);
    });
  }

  return {
    getUserId,
    getUser,
    getUserPoints,
    getInstallFlags,
    getAnonymousId,
    isPieEmployee,
    start,
  };
}
