import { gql } from '@apollo/client/core';
import { debounce } from 'radash';
import browser from 'webextension-polyfill';
import { ContentRoutingFunc, RouteData } from '@shared/contentScript';
import { ExtensionMessaging } from '@shared/messages/createExtensionMessaging';
import { ExternalExtensionMessaging } from '@shared/messages/createExternalExtensionMessaging';
import { WEBSITE_BASE_URL } from '@shared/utils/baseUrl';
import { MetricsManager } from '@background/analytics/createMetricsManager';
import { GraphQLClient } from '@background/api/createGraphQLClient';
import { FeatureManager } from '@background/features/createFeatureManager';
import { BrowserStorage } from '@background/storage/createStorage';
import { TabManager } from '@background/tabs/createTabManager';
import { UserManager } from '@background/user/createUserManager';

export type AdblockReviewManagerParameters = {
  externalMessages: ExternalExtensionMessaging;
  featureManager: FeatureManager;
  graphQLClient: GraphQLClient;
  messages: ExtensionMessaging;
  metricsManager: MetricsManager;
  storage: BrowserStorage;
  tabManager: TabManager;
  userManager: UserManager;
};

export interface AdblockReviewManager {
  start: () => void;
  getContent: ContentRoutingFunc;
}

type OpenTrustPilotPopupPayload = {
  top: number;
  left: number;
  width: number;
  height: number;
};

const TRUSTPILOT_REDIRECT_URL = `${WEBSITE_BASE_URL}/reviews/trustpilot`;
const TRUSTPILOT_DEFAULT_REVIEW_URL = 'https://www.trustpilot.com/evaluate/pie.org';
const TRUSTPILOT_API_KEY = '2iBEARP5wfif7Xe3mpdSjLP7ukCH22lG'; // public key, not a secret
const TRUSTPILOT_LINK_API_URL = 'https://invitations-api.trustpilot.com/v1/private/business-units/671a9ec5abca7bf5a7e94577/invitation-links';

const createAdblockReviewManager = ({
  externalMessages,
  featureManager,
  graphQLClient,
  messages,
  metricsManager,
  storage,
  tabManager,
  userManager,
}: AdblockReviewManagerParameters) => {
  const NEW_TIME = 1000 * 60 * 60 * 24 * 7 * 2; // 2 weeks in ms
  const REVIEW_COOLDOWN = 1000 * 60 * 60 * 24 * 30; // 1 month in ms
  const SHOW_LIMIT_BASE = 1000;
  const SHOW_LIMIT_INCREMENT = 10000;
  const SHOW_LIMIT_CACHE_KEY = 'adblockReview:showLimit';
  const SHOWN_CACHE_KEY = 'adblockReview:shown';
  const REVIEWED_CACHE_KEY = 'adblockReview:reviewed';
  const TRUSTPILOT_CACHE_KEY = 'adblockReview:trustpilot';
  const EMBEDDED_REVIEW_COOLDOWN = 1000 * 60 * 60 * 24 * 7; // 1 week in ms
  const EMBEDDED_SHOWN_CACHE_KEY = 'adblockReview:embedded:shown';
  let trustPilotPopupTab: browser.Tabs.Tab | null = null;

  async function setAdblockReviewShown() {
    await storage.set(SHOWN_CACHE_KEY, Date.now(), REVIEW_COOLDOWN);
  }

  async function setEmbeddedAdblockReviewShown() {
    await storage.set(EMBEDDED_SHOWN_CACHE_KEY, Date.now(), EMBEDDED_REVIEW_COOLDOWN);
  }

  async function setAdblockReviewed() {
    await storage.set(REVIEWED_CACHE_KEY, Date.now());

    const showLimit = (await storage.get(SHOW_LIMIT_CACHE_KEY)) as number | null;
    let newShowLimit = SHOW_LIMIT_INCREMENT;
    if (showLimit && showLimit > SHOW_LIMIT_INCREMENT) {
      newShowLimit += SHOW_LIMIT_INCREMENT;
    }
    await storage.set(SHOW_LIMIT_CACHE_KEY, newShowLimit);
  }

  function isEdge() {
    // Check if the browser is Edge by checking the user agent
    const { userAgent } = navigator;
    return userAgent.includes('Edg/');
  }

  async function canShowReview() {
    // Disabled on Edge for now before store listing exists
    if (isEdge()) {
      return false;
    }

    // If the user has already reviewed, don't show it
    const lastReviewed = await storage.get(REVIEWED_CACHE_KEY);
    if (lastReviewed) {
      return false;
    }

    // If the user has recently seen the popup, don't show it
    const lastShown = await storage.get(SHOWN_CACHE_KEY);
    if (lastShown) {
      return false;
    }

    // If the user hasn't blocked enough ads, don't show it
    const showLimit = (await storage.get(SHOW_LIMIT_CACHE_KEY)) as number | null;
    const adsBlocked = ((await metricsManager.getDeviceMetric('adPlacementsSeen')) as number | undefined) || 0;
    if (!showLimit) {
      // If the show limit is not set, set it to the base value
      await storage.set(SHOW_LIMIT_CACHE_KEY, SHOW_LIMIT_BASE + adsBlocked);
      return false;
    }
    if (adsBlocked < showLimit) {
      return false;
    }

    // If the user is not logged in, don't show it
    const user = await userManager.getUser({});
    if (!user?.userId) {
      return false;
    }

    // Check if new user
    const newUser = user.created > Date.now() - NEW_TIME;

    // Check if new extension install
    const extInstallTime = (await storage.get('extInstallTime')) as number | null;
    let newExt = false;
    if (!extInstallTime) {
      newExt = true;
    } else {
      newExt = extInstallTime > Date.now() - NEW_TIME;
    }

    // If too new, don't show it
    if (newUser && newExt) {
      return false;
    }

    return true;
  }

  async function loadEmbeddedReview(sender: browser.Runtime.MessageSender) {
    // Disabled on Edge for now before store listing exists
    if (isEdge()) {
      return false;
    }

    // If the user has already reviewed, don't show it
    const lastReviewed = await storage.get(REVIEWED_CACHE_KEY);
    if (lastReviewed) {
      return false;
    }

    // If the user has recently seen the embedded review, don't show it
    const lastShown = await storage.get(EMBEDDED_SHOWN_CACHE_KEY);
    if (lastShown) {
      return false;
    }

    // If the feature flag is disabled, don't show it
    const isEnabled = await featureManager.getFeatureFlagEnabled('embedded_adblock_review');
    if (!isEnabled) {
      return false;
    }

    if (sender.tab?.id === undefined) {
      return false;
    }
    const tabId = sender.tab.id;

    // If the user is not logged in, don't show it
    const user = await userManager.getUser({});
    if (!user?.userId) {
      return false;
    }

    // Check if new user
    const newUser = user.created > Date.now() - NEW_TIME;

    // Check if new extension install
    const extInstallTime = (await storage.get('extInstallTime')) as number | null;
    let newExt = false;
    if (!extInstallTime) {
      newExt = true;
    } else {
      newExt = extInstallTime > Date.now() - NEW_TIME;
    }

    // If too new, don't show it
    if (newUser && newExt) {
      return false;
    }

    // Success! Show embedded review
    messages.sendToTab(tabId, 'adblockEmbeddedUI:show', { type: 'review' });

    return true;
  }

  async function closeTrustPilotPopup() {
    if (trustPilotPopupTab?.id) {
      await browser.tabs.remove(trustPilotPopupTab.id);
      trustPilotPopupTab = null;
    }
  }

  function trustPilotTabListener(tabChangedId: number, changeInfo: browser.Tabs.OnUpdatedChangeInfoType) {
    if (trustPilotPopupTab?.id === tabChangedId) {
      if (changeInfo.status === 'complete') {
        browser.scripting.executeScript({
          target: { tabId: trustPilotPopupTab.id },
          func() {
            const TRUSTPILOT_NAME_FIELD_ID = 'review-invitation-name';
            const observer = new MutationObserver(() => {
              const inputElement = document.getElementById(TRUSTPILOT_NAME_FIELD_ID) as HTMLInputElement;
              if (inputElement) {
                inputElement.value = '';
                inputElement.dispatchEvent(new Event('change', { bubbles: true }));
                observer.disconnect();
              }
            });
            observer.observe(document, {
              childList: true,
              subtree: true,
            });
          },
        });
      }

      if (changeInfo.url?.includes('/reviews/trustpilot')) {
        setTimeout(() => {
          setAdblockReviewed();
          closeTrustPilotPopup();
          browser.tabs.onUpdated.removeListener(trustPilotTabListener);
        }, 7000);
      }
    }
  }

  async function openTrustPilotPopup({ top, left, width, height }: OpenTrustPilotPopupPayload) {
    const reviewLink = (await storage.get(TRUSTPILOT_CACHE_KEY)) as string | null;
    browser.tabs.onUpdated.addListener(trustPilotTabListener);
    if (typeof browser.windows.create !== 'function') {
      const tab = await tabManager.createTabNextToCurrentTab({
        url: reviewLink || TRUSTPILOT_DEFAULT_REVIEW_URL,
      });
      trustPilotPopupTab = tab;
    } else {
      // for desktop browsers, open in a new popup window
      const win = await browser.windows.create({
        url: `${reviewLink || TRUSTPILOT_DEFAULT_REVIEW_URL}?isPopup=true`,
        type: 'popup',
        width: Math.floor(width),
        height: Math.floor(height),
        left: Math.floor(left),
        top: Math.floor(top),
      });
      trustPilotPopupTab = win?.tabs?.[0] || null;
    }
  }

  async function getTrustPilotReviewLink(): Promise<string> {
    // get user info
    const user = await userManager.getUser({});
    // user email and name required for trustpilot review link
    if (user?.email) {
      const tpAccessTokenRes = await graphQLClient.query({
        query: gql`
          query ext_getTrustPilotAccessToken {
            getTrustPilotAccessToken
          }
        `,
      });
      const trustPilotAccessToken = tpAccessTokenRes?.data?.getTrustPilotAccessToken;

      // return default trustpilot link if no access token
      if (trustPilotAccessToken) {
        // get trustpilot user-specific review link
        const reviewLinkRes = await fetch(TRUSTPILOT_LINK_API_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            apiKey: TRUSTPILOT_API_KEY,
            Authorization: `Bearer ${trustPilotAccessToken}`,
          },
          body: JSON.stringify({
            email: user?.email,
            name: 'Pie User',
            locale: 'en-US',
            tags: ['extension'],
            redirectUri: TRUSTPILOT_REDIRECT_URL,
          }),
        });

        if (reviewLinkRes.ok) {
          const reviewLinkData = await reviewLinkRes.json();
          const reviewLink = reviewLinkData.url;
          if (reviewLink) {
            await storage.set(TRUSTPILOT_CACHE_KEY, reviewLink);
            return reviewLink;
          }
        }
      }
    }

    return TRUSTPILOT_DEFAULT_REVIEW_URL;
  }

  const getContent: ContentRoutingFunc = async (sender): Promise<RouteData | null> => {
    // Testing bypass
    if (sender.url?.includes('adblockReview=1')) {
      return { pathname: '/review' };
    }

    // Testing bypass
    if (sender.url?.includes('trustpilotReview=1')) {
      return { pathname: '/trustpilot' };
    }

    const isEnabled = featureManager ? await featureManager.getFeatureFlagEnabled('adblock-review-popup') : true;

    let canShow = false;

    if (isEnabled) {
      canShow = await canShowReview();
    }

    if (!canShow) {
      loadEmbeddedReview(sender);
      return null;
    }

    if (featureManager) {
      const results = await featureManager.getExperimentFeatureFlagAndVariant('trust_pilot_reviews');
      const { enabled: trustPilotEnabled, variant: trustPilotVariant } = results;
      if (trustPilotEnabled && trustPilotVariant === `trust_pilot`) {
        return { pathname: '/trustpilot' };
      }
    }

    return { pathname: '/review' };
  };

  function start() {
    // Debounce in development to not double count from useEffect firing twice in strict mode
    const debouncedSetAdblockReviewShown = process.env.NODE_ENV === 'development' ? debounce({ delay: 50 }, setAdblockReviewShown) : setAdblockReviewShown;
    const debouncedSetEmbeddedAdblockReviewShown =
      process.env.NODE_ENV === 'development' ? debounce({ delay: 50 }, setEmbeddedAdblockReviewShown) : setEmbeddedAdblockReviewShown;

    messages.addListener('adblockReview:action:setAdblockReviewShown', async () => {
      debouncedSetAdblockReviewShown();
    });

    messages.addListener('adblockReview:embedded:action:setAdblockReviewShown', async () => {
      debouncedSetEmbeddedAdblockReviewShown();
    });

    messages.addListener('adblockReview:action:setAdblockReviewed', async () => {
      await setAdblockReviewed();
    });

    messages.addListener('adblockReview:action:openTrustPilotPopup', async (message: any) => {
      await openTrustPilotPopup(message);
    });

    messages.addListener('adblockReview:action:getTrustPilotReviewLink', async () => {
      getTrustPilotReviewLink();
    });

    externalMessages.addListener('adblockReview:action:closeTrustPilotPopup', async () => {
      closeTrustPilotPopup();
      browser.tabs.onUpdated.removeListener(trustPilotTabListener);
    });
  }

  return {
    start,
    getContent,
  };
};

export default createAdblockReviewManager;
