import { gql } from '@apollo/client';
import { fromUrl, parseDomain, ParseResultType } from 'parse-domain';
import { Runtime } from 'webextension-polyfill';
import { EventTypes } from '@shared/analytics/eventTypes';
import { PIE_SHOPPING_ID } from '@shared/constants';
import { ContentRoutingFunc, RouteData } from '@shared/contentScript';
import { ExtensionMessaging } from '@shared/messages/createExtensionMessaging';
import { ExternalExtensionMessaging } from '@shared/messages/createExternalExtensionMessaging';
import { MessageNames } from '@shared/messages/messageNames';
import { NotificationTypes } from '@shared/notifications/types';
import { STATIC_BASE_URL } from '@shared/utils/baseUrl';
import { Analytics } from '@background/analytics/createAnalytics';
import { GraphQLClient } from '@background/api/createGraphQLClient';
import { ExtensionsManagementManager } from '@background/extensionsManagement/createExtensionsManagementManager';
import { FeatureManager } from '@background/features/createFeatureManager';
import { NotificationManager } from '@background/notifications/createNotificationManager';
import { BrowserStorage } from '@background/storage/createStorage';
import { TabManager } from '@background/tabs/createTabManager';
import { UserManager } from '@background/user/createUserManager';

export type CreateShoppingXSellManagerParams = {
  analytics: Analytics;
  extensionsManagement: ExtensionsManagementManager;
  externalMessages: ExternalExtensionMessaging;
  featureManager: FeatureManager;
  graphQLClient: GraphQLClient;
  messages: ExtensionMessaging;
  notificationManager: NotificationManager;
  storage: BrowserStorage;
  tabManager: TabManager;
  userManager: UserManager;
};

export type ShoppingXSellManager = {
  getContent: ContentRoutingFunc;
  start: () => void;
};

type ShoppingXSellData = Partial<Record<string, { id: string; url: string }[]>>;

type State = {
  id: string;
  url: string;
  type: string;
  value: number;
};

export default function createShoppingXSellManager({
  analytics,
  extensionsManagement,
  externalMessages,
  featureManager,
  graphQLClient,
  messages,
  notificationManager,
  storage,
  tabManager,
  userManager,
}: CreateShoppingXSellManagerParams): ShoppingXSellManager {
  const isChrome = process.env.PLATFORM === 'ch';

  const SNOOZE_KEY = 'shoppingXSellSnoozed';

  const REDEEMED_KEY = 'shoppingXSellIsRedeemed';

  const CACHE_KEY = 'shoppingXSellData';

  const SHOWN_KEY = 'shoppingXSellShown';

  const ONE_DAY_IN_MS = 1000 * 60 * 60 * 24;

  const ONE_WEEK_IN_MS = 1000 * 60 * 60 * 24 * 7;

  const ONE_MONTH_IN_MS = 1000 * 60 * 60 * 24 * 30;

  async function fetchShoppingXSellData(): Promise<ShoppingXSellData> {
    const cached = (await storage.get(CACHE_KEY)) as ShoppingXSellData | null;
    if (cached) {
      return cached;
    }

    const res = await fetch(`${STATIC_BASE_URL}/data/shopping-x-sell.json`);

    const data = await res.json();

    await storage.set(CACHE_KEY, data, ONE_WEEK_IN_MS);

    return data;
  }

  async function getIdAndPartialFromUrl(url: string): Promise<{ id: string; url: string } | null> {
    const parsed = parseDomain(fromUrl(url));

    if (parsed.type !== ParseResultType.Listed) {
      return null;
    }

    const tld = parsed.topLevelDomains.join('.');
    const domain = parsed.domain ? `${parsed.domain}.${tld}` : tld;

    const data = await fetchShoppingXSellData();

    const partials = data[domain];

    if (!partials || partials.length === 0) {
      return null;
    }

    let id: string | null = null;
    let partialUrl: string | null = null;
    let matchLength = 0;
    partials.forEach((partial) => {
      if (url.includes(partial.url) && partial.url.length > matchLength) {
        const nextChar = url[partial.url.length + url.indexOf(partial.url)];
        if (nextChar === undefined || nextChar === '/' || nextChar === '.' || nextChar === '?') {
          id = partial.id;
          partialUrl = partial.url;
          matchLength = partial.url.length;
        }
      }
    });

    if (!id || !partialUrl) {
      return null;
    }

    return {
      id,
      url: partialUrl,
    };
  }

  async function getXSellDataById(id: string): Promise<{ type: string; value: number } | null> {
    const { data } = await graphQLClient.query<{ getShoppingXSellDataById: { type: string; value: number; isActive: boolean } | null }, { id: string }>({
      query: gql`
        query ext_getShoppingXSellDataById($id: ID!) {
          getShoppingXSellDataById(id: $id) {
            value
            type
            isActive
          }
        }
      `,
      variables: { id },
    });

    if (!data?.getShoppingXSellDataById?.isActive) {
      return null;
    }

    return data?.getShoppingXSellDataById || null;
  }

  async function hasPreviouslyRedeemed(): Promise<boolean> {
    const cached = (await storage.get(REDEEMED_KEY)) as boolean | null;
    if (cached) {
      return cached;
    }

    const { data, error } = await graphQLClient.query<
      { checkOnboardingTransaction: boolean },
      { userId: string; onboardingType: string; client: { type: string; version: string } }
    >({
      query: gql`
        query checkOnboardingTransaction($userId: ID!, $onboardingType: OnboardingType!, $client: OnboardingClient) {
          checkOnboardingTransaction(userId: $userId, onboardingType: $onboardingType, client: $client)
        }
      `,
      variables: {
        // userId is not actually used but we need to include it to avoid schema breaking change
        userId: '',
        onboardingType: 'X_SELL',
        client: {
          type: 'EXTENSION',
          version: process.env.VERSION as string,
        },
      },
    });

    // ensure we don't show the prompt if there's an error
    if (error) {
      return true;
    }

    // if the user has previously redeemed, snooze forever (no ttl)
    if (data.checkOnboardingTransaction) {
      await storage.set(REDEEMED_KEY, true);
      return true;
    }

    return false;
  }

  async function getContent({ tab }: Runtime.MessageSender): Promise<RouteData<State> | null> {
    if (!isChrome) {
      return null;
    }

    if (!tab?.url) {
      return null;
    }

    const isSnoozed = await storage.get(SNOOZE_KEY);
    if (isSnoozed) {
      return null;
    }

    const isAlreadyInstalled = await extensionsManagement.hasShoppingInstalled();
    if (isAlreadyInstalled) {
      return null;
    }

    const idAndPartial = await getIdAndPartialFromUrl(tab.url);
    if (!idAndPartial) {
      return null;
    }

    const { id, url } = idAndPartial;

    const data = await getXSellDataById(id);
    if (!data) {
      return null;
    }

    let isPreviouslyRedeemed = false;
    const userId = await userManager.getUserId();
    if (userId) {
      isPreviouslyRedeemed = await hasPreviouslyRedeemed();
    }

    if (isPreviouslyRedeemed) {
      return null;
    }

    const state: State = {
      id,
      url,
      ...data,
    };

    // snooze for one day on show
    // if user explicitly closes or manually snoozes, the time will be extended
    await Promise.all([storage.set(SNOOZE_KEY, true, ONE_DAY_IN_MS), storage.set(SHOWN_KEY, state, ONE_MONTH_IN_MS)]);

    const EXP_NAME = 'ext_xsell_popup_v2';
    const expResults = await featureManager.getExperimentFeatureFlagAndVariant(EXP_NAME);
    const { enabled: expEnabled, variant: expVariant } = expResults as { enabled: boolean; variant: string };
    if (expEnabled) {
      messages.send(
        'featureManager:action:viewExperiment',
        {
          flagName: EXP_NAME,
          variantName: expVariant,
        },
        { destination: 'background' },
      );
      if (expVariant === 'banner_overlay') {
        return {
          pathname: '/shopping_x_sell_banner',
          state,
        };
      }
      if (expVariant === 'popup_slim') {
        return {
          pathname: '/shopping_x_sell_slim',
          state,
        };
      }
    }
    // control
    return {
      pathname: '/shopping_x_sell',
      state,
    };
  }

  async function handleSnooze(message: any): Promise<void> {
    const { ttl } = message as { ttl: number };
    await storage.set(SNOOZE_KEY, true, ttl);
  }

  let pendingRedemption: Promise<{ destinationUrl: string } | null> | null = null;
  async function maybeRedeem(): Promise<{ destinationUrl: string } | null> {
    const createPendingRedemptionPromise = async (): Promise<{ destinationUrl: string } | null> => {
      // only applicable to Chrome where this is multiple extensions
      if (process.env.PLATFORM !== 'ch') {
        return null;
      }

      const isShoppingInstalled = await extensionsManagement.hasShoppingInstalled();
      if (!isShoppingInstalled) {
        return null;
      }

      const userId = await userManager.getUserId();
      if (!userId) {
        return null;
      }

      const isPreviouslyRedeemed = await hasPreviouslyRedeemed();
      if (isPreviouslyRedeemed) {
        return null;
      }

      const { data } = await graphQLClient.mutate<{ createOnboardingTransaction: boolean }, { userId: string; onboardingType: string }>({
        mutation: gql`
          mutation createOnboardingTransaction($userId: ID!, $onboardingType: OnboardingType!) {
            createOnboardingTransaction(userId: $userId, onboardingType: $onboardingType)
          }
        `,
        variables: { userId: '', onboardingType: 'X_SELL' },
      });

      // set redeemed key as long as there are no API errors
      await storage.set(REDEEMED_KEY, true);

      if (data?.createOnboardingTransaction) {
        const state = (await storage.get(SHOWN_KEY)) as State | null;

        analytics.track(EventTypes.SHOPPING_X_SELL, {
          action: 'redeem',
          surface: 'redeem_notification',
          id: state?.id,
          type: state?.type,
          value: state?.value,
          rewardsAmount: 50,
        });

        const tab = await tabManager.getCurrent();
        await notificationManager.showNotification(
          { tabId: tab?.id! },
          {
            type: NotificationTypes.SHOPPING_X_SELL_REDEEMED,
            state,
          },
        );

        if (state?.url) {
          externalMessages.send(PIE_SHOPPING_ID, 'merchant:action:activateRewards', {
            merchantId: state.id,
            rewards: {
              rewardsType: state.type,
              rewardsValue: state.value,
            },
          });
          const destinationUrl = state?.url.startsWith('http') ? state.url : `https://${state.url}`;
          return { destinationUrl };
        }
      }

      return null;
    };

    // shopping and website may both call this about the same time
    // ensure we only process once
    if (!pendingRedemption) {
      pendingRedemption = createPendingRedemptionPromise().then((res) => {
        pendingRedemption = null;
        return res;
      });
    }

    return pendingRedemption;
  }

  function start() {
    messages.addListener(MessageNames.SHOPPING_X_SELL_SNOOZE, handleSnooze);
    externalMessages.addListener(MessageNames.SHOPPING_X_SELL_REDEEM, maybeRedeem);

    // check to see if x-sell should be redeemed
    maybeRedeem();
  }

  return {
    getContent,
    start,
  };
}
