import { gql } from '@apollo/client';
import { Runtime } from 'webextension-polyfill';
import { ContentRoutingFunc, RouteData } from '@shared/contentScript';
import { ExtensionMessaging } from '@shared/messages/createExtensionMessaging';
import { MessageNames } from '@shared/messages/messageNames';
import { NotificationTypes } from '@shared/notifications/types';
import { OnboardingTransactionTypes, ONBOARDING_TRANSACTION_POINTS } from '@shared/onboardingTransactions';
import { parseUrl } from '@shared/utils/url';
import { GraphQLClient } from '@background/api/createGraphQLClient';
import { NotificationManager } from '@background/notifications/createNotificationManager';
import { BrowserStorage } from '@background/storage/createStorage';
import { TabManager } from '@background/tabs/createTabManager';
import { UserManager } from '@background/user/createUserManager';

type RedeemOptions = {
  onRedeem?: () => void;
};

export type OnboardingTransactionsManager = {
  checkPreviouslyRedeemed: (type: OnboardingTransactionTypes) => Promise<boolean>;
  maybeRedeem: (type: OnboardingTransactionTypes, options?: RedeemOptions) => Promise<void>;
  start: () => void;
  getContent: ContentRoutingFunc;
};

export type CreateOnboardingTransactionsManagerParams = {
  graphQLClient: GraphQLClient;
  messages: ExtensionMessaging;
  notificationManager: NotificationManager;
  storage: BrowserStorage;
  tabManager: TabManager;
  userManager: UserManager;
};

type PendingTransactionState = {
  type: OnboardingTransactionTypes;
};

const ONE_DAY_IN_MS = 1000 * 60 * 60 * 24;

export default function createOnboardingTransactionsManager({
  graphQLClient,
  messages,
  notificationManager,
  storage,
  tabManager,
  userManager,
}: CreateOnboardingTransactionsManagerParams): OnboardingTransactionsManager {
  const LOGIN_TO_REDEEM_TRANSACTIONS: Partial<Record<number, PendingTransactionState>> = {};

  function getStorageKeyRedeemed(type: OnboardingTransactionTypes): string {
    return `onboardingTransactionsRedeemed:${type}`;
  }

  async function checkPreviouslyRedeemed(type: OnboardingTransactionTypes): Promise<boolean> {
    const userId = await userManager.getUserId();
    if (!userId) {
      return false;
    }

    const storageKeyRedeemed = getStorageKeyRedeemed(type);

    const cached = (await storage.get(storageKeyRedeemed)) as boolean | null;
    if (cached) {
      return cached;
    }

    const { data, error } = await graphQLClient.query<
      { checkOnboardingTransaction: boolean },
      { userId: string; onboardingType: string; client: { type: string; version: string } }
    >({
      query: gql`
        query checkOnboardingTransaction($userId: ID!, $onboardingType: OnboardingType!, $client: OnboardingClient) {
          checkOnboardingTransaction(userId: $userId, onboardingType: $onboardingType, client: $client)
        }
      `,
      variables: {
        // userId is not actually used but we need to include it to avoid schema breaking change
        userId: '',
        onboardingType: type,
        client: {
          type: 'EXTENSION',
          version: process.env.VERSION as string,
        },
      },
    });

    // ensure we don't show the prompt if there's an error
    if (error) {
      return true;
    }

    // if the user has previously redeemed, snooze forever (no ttl)
    if (data.checkOnboardingTransaction) {
      await storage.set(storageKeyRedeemed, true);
      return true;
    }

    return false;
  }

  async function maybeRedeem(type: OnboardingTransactionTypes, options?: RedeemOptions) {
    const tab = await tabManager.getCurrent();

    const userId = await userManager.getUserId();
    if (!userId) {
      LOGIN_TO_REDEEM_TRANSACTIONS[tab?.id!] = {
        type,
      };

      return;
    }

    const isPreviouslyRedeemed = await checkPreviouslyRedeemed(type);
    if (isPreviouslyRedeemed) {
      return;
    }

    const { data } = await graphQLClient.mutate<{ createOnboardingTransaction: boolean }, { userId: string; onboardingType: string }>({
      mutation: gql`
        mutation createOnboardingTransaction($userId: ID!, $onboardingType: OnboardingType!) {
          createOnboardingTransaction(userId: $userId, onboardingType: $onboardingType)
        }
      `,
      variables: { userId: '', onboardingType: type },
    });

    if (data?.createOnboardingTransaction) {
      const storageKeyRedeemed = getStorageKeyRedeemed(type);
      await storage.set(storageKeyRedeemed, true);

      options?.onRedeem?.();

      await notificationManager.showNotification(
        { tabId: tab?.id! },
        {
          type: NotificationTypes.POINTS_EARNED,
          state: {
            points: ONBOARDING_TRANSACTION_POINTS,
          },
        },
      );
    }
  }

  async function getContent({ tab }: Runtime.MessageSender): Promise<RouteData | null> {
    const url = parseUrl(tab?.url);
    if (!tab?.id || !url) {
      return null;
    }

    if (LOGIN_TO_REDEEM_TRANSACTIONS[tab?.id!]) {
      const pendingTransaction = LOGIN_TO_REDEEM_TRANSACTIONS[tab.id!];
      const { type } = pendingTransaction as PendingTransactionState;

      delete LOGIN_TO_REDEEM_TRANSACTIONS[tab.id!];

      await notificationManager.showNotification(
        { tabId: tab?.id! },
        {
          options: {
            cooldown: ONE_DAY_IN_MS,
          },
          type: NotificationTypes.ONBOARDING_TRANSACTIONS_LOGIN,
          state: {
            type,
          },
        },
      );
    }

    return null;
  }

  async function handleRedeem(message: any, sender: Runtime.MessageSender) {
    const tabId = sender.tab?.id;

    if (!tabId) {
      return;
    }

    const { type } = message;

    maybeRedeem(type);
  }

  function start() {
    messages.addListener(MessageNames.ONBOARDING_TRANSACTIONS_REDEEM, handleRedeem);
  }

  return {
    checkPreviouslyRedeemed,
    getContent,
    maybeRedeem,
    start,
  };
}
